data.code:
param sqlServerName string
param sqlAdminLogin string
param sqlAdminPassword string
param location string = resourceGroup().location

resource sqlServer 'Microsoft.Sql/servers@2021-11-01' = {
  name: sqlServerName
  location: location
  properties: {
    administratorLogin: sqlAdminLogin
    administratorLoginPassword: sqlAdminPassword
    minimalTlsVersion: '1.2'
    publicNetworkAccess: 'Enabled'
  }
}

resource sqlDatabase 'Microsoft.Sql/servers/databases@2021-11-01' = {
  name: '${sqlServer.name}/myapp-db'
  location: location
  sku: {
    name: 'S0'
    tier: 'Standard'
  }
  dependsOn: [sqlServer]
}

resource firewallRule 'Microsoft.Sql/servers/firewallRules@2021-11-01' = {
  name: '${sqlServer.name}/AllowAzureServices'
  properties: {
    startIpAddress: '0.0.0.0'
    endIpAddress: '0.0.0.0'
  }
  dependsOn: [sqlServer]
}

resource serviceBus 'Microsoft.ServiceBus/namespaces@2023-01-01-preview' = {
  name: 'myapp-sb-${uniqueString(resourceGroup().id)}'
  location: resourceGroup().location
  sku: {
    name: 'Standard'
    tier: 'Standard'
    capacity: 1
  }
}

resource serviceBusQueue 'Microsoft.ServiceBus/namespaces/queues@2023-01-01-preview' = {
  name: '${serviceBus.name}/orders-queue'
  properties: {
    maxSizeInMegabytes: 1024
    lockDuration: 'PT30S'
    maxDeliveryCount: 10
  }
  dependsOn: [serviceBus]
}
